import type { ThemeConfig } from 'antd';
import generatedTheme from '@fms-tokens/dist/antd/theme.json';

/**
 * Runtime Ant Design theme for FMS.
 *
 * `tokens/dist/antd/theme.json` is generated by `npm run tokens:build` and must
 * not be edited. It is a Figma/W3C-oriented seed, not a valid ConfigProvider
 * payload as-is. This module is the only place that adapts it.
 *
 * Required conversions (see docs/token-mapping.md):
 * - drop `meta` (not an Ant Design theme key)
 * - `lineHeight` 24 is px; Ant seed `lineHeight` is a ratio (24 / fontSize 16 = 1.5)
 * - append a system font fallback to `fontFamily`
 * - add control heights from size tokens (not present on the generated seed)
 *
 * Control heights are copied from `tokens/dist/foundation/size.resolved.json`
 * (`Size.Height.controlHeight*`) so the library does not bundle that file.
 */
const { token: generatedToken } = generatedTheme;

/** Size.Height.controlHeight — Ant middle / FMS small */
const CONTROL_HEIGHT = 32;
/** Size.Height.controlHeightLG — Ant large / FMS base */
const CONTROL_HEIGHT_LG = 40;
/** Size.Height.controlHeightSM — Ant small / FMS x-small */
const CONTROL_HEIGHT_SM = 24;

/** Colors.Brand.Primary.colorPrimaryBg — `tokens/dist/foundation/colors.resolved.json` */
const COLOR_PRIMARY_BG = '#C7EBEA';

const fontSize = generatedToken.fontSize;

export const antdTheme: ThemeConfig = {
  cssVar: true,
  token: {
    ...generatedToken,
    lineHeight: fontSize ? generatedToken.lineHeight / fontSize : 1.5,
    fontFamily: `${generatedToken.fontFamily}, -apple-system, BlinkMacSystemFont, sans-serif`,
    controlHeight: CONTROL_HEIGHT,
    controlHeightLG: CONTROL_HEIGHT_LG,
    controlHeightSM: CONTROL_HEIGHT_SM,
    colorPrimaryBg: COLOR_PRIMARY_BG,
    colorLink: generatedToken.colorPrimary,
    colorLinkHover: generatedToken.colorPrimaryHover,
    colorLinkActive: generatedToken.colorPrimaryActive,
    colorBgContainerDisabled: '#E4E4E4',
    colorTextDisabled: 'rgba(0, 0, 0, 0.25)',
  },
  components: {
    Button: {
      borderRadius: 6,
      borderRadiusLG: 8,
      borderRadiusSM: 4,
      paddingInline: 12,
      paddingInlineLG: 16,
      paddingInlineSM: 8,
      contentFontSize: 14,
      contentFontSizeLG: 16,
      contentFontSizeSM: 14,
      fontWeight: 400,
      defaultShadow: '0 2px 0 rgba(0, 0, 0, 0.02)',
      primaryShadow: '0 2px 0 rgba(217, 217, 217, 0.1)',
      defaultBg: '#FFFFFF',
      defaultBorderColor: '#D9D9D9',
      defaultColor: 'rgba(0, 0, 0, 0.88)',
      borderColorDisabled: '#D9D9D9',
      primaryColor: '#FFFFFF',
      dangerColor: '#FFFFFF',
    },
    Breadcrumb: {
      fontSize: 14,
      itemColor: 'rgba(0, 0, 0, 0.88)',
      lastItemColor: 'rgba(0, 0, 0, 0.55)',
      linkColor: 'rgba(0, 0, 0, 0.88)',
      linkHoverColor: 'rgba(0, 0, 0, 0.88)',
      separatorColor: 'rgba(0, 0, 0, 0.55)',
      separatorMargin: 8,
      iconFontSize: 14,
    },
    Badge: {
      indicatorHeight: 20,
      indicatorHeightSM: 16,
      dotSize: 8,
      textFontSize: 14,
      textFontSizeSM: 8,
      textFontWeight: 400,
    },
  },
};

export function createAntdTheme(overrides?: ThemeConfig): ThemeConfig {
  return {
    ...antdTheme,
    ...overrides,
    token: {
      ...antdTheme.token,
      ...overrides?.token,
    },
    components: {
      ...antdTheme.components,
      ...overrides?.components,
    },
  };
}
